module top_module(
  input clk,
  input rst,
  input [11:0] temp_in,
  input [11:0] press_in,
  input [11:0] hum_in,
  output reg [15:0] temp_out,
  output reg [15:0] press_out,
  output reg [15:0] hum_out
);reg [7:0] counter = 0;
  reg [15:0] temp_out_reg = 16'b0;
  reg [15:0] press_out_reg = 16'b0;
  reg [15:0] hum_out_reg = 16'b0;

  always @(posedge clk) begin
    if (rst) begin
      counter <= 0;
      temp_out_reg <= 16'b0;
      press_out_reg <= 16'b0;
      hum_out_reg <= 16'b0;
    end
    else begin
      counter <= counter + 1;
      if (counter == 100) begin
        temp_out_reg <= {temp_in, 4'b0000};
        press_out_reg <= {press_in, 4'b0001};
        hum_out_reg <= {hum_in, 4'b0010};
        counter <= 0;
      end
    end
    temp_out <= temp_out_reg;
    press_out <= press_out_reg;
    hum_out <= hum_out_reg;
  end

endmodule

