module top_module(clk,sclk, reset);input wire clk;  
	input wire reset;
	output wire sclk; 


	reg [16:0] count; 


	always @ (posedge clk, posedge reset) 
	begin
			if (reset) count <= 0;


			else count <= count + 1;

	end


	assign sclk = count[16];


endmodule

