Implement a pre-decoder circuit that analyzes a 6-bit input address. The circuit generates a one-bit output signal `pre_dec_o` based on specific address ranges, indicating whether the address corresponds to clock domain #0 (output low) or clock domain #1 (output high). If the input address falls outside the predetermined ranges, an error signal `pre_dec_err_o` is activated, indicating an invalid address condition.
module top_module(
    input [5:0] addr_i,
    output reg pre_dec_o,
    output reg pre_dec_err_o
);

code:
module top_module(
    input [5:0] addr_i,
    output reg pre_dec_o,
    output reg pre_dec_err_o
);reg pre_dec;
reg pre_dec_err;

assign pre_dec_o = pre_dec;
assign pre_dec_err_o = pre_dec_err;

always @ (addr_i) begin
    pre_dec = 0;
    pre_dec_err = 0;
    case (addr_i[5:2])
        // clock-domain #0 --> clk_a
        'h0, 'h8, 'ha: pre_dec = 0;
        // clock-domain #1 --> clk_f20
        'h1, 'h2, 'h3, 'h4, 'h5, 'h6, 'h7: pre_dec = 1;
        default: begin 
            pre_dec = 0;
            pre_dec_err = 1;
        end
    endcase
end

endmodule

