code:
module fifo(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in    ,
    input               read        ,

    output  reg [7:0]   data_out
);

    reg [7:0] fifo_mem [7:0];
    reg [2:0] write_ptr;
    reg [2:0] read_ptr;
    reg [2:0] count;

    // Write logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            write_ptr <= 0;
        end else if (valid_in && (count < 8)) begin
            fifo_mem[write_ptr] <= data_in;
            write_ptr <= write_ptr + 1;
        end
    end

    // Read logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            read_ptr <= 0;
            data_out <= 0;
        end else if (read && (count > 0)) begin
            data_out <= fifo_mem[read_ptr];
            read_ptr <= read_ptr + 1;
        end
    end

    // Count logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= 0;
        end else if (valid_in && (count < 8) && !read) begin
            count <= count + 1;
        end else if (read && (count > 0) && !valid_in) begin
            count <= count - 1;
        end else if (valid_in && (count < 8) && read && (count > 0)) begin
            count <= count;
        end
    end

endmodule

