module top_module(dataExt, dataInt, oe, clk, rst);inout[31:0] dataExt, dataInt;
	input oe, clk, rst;

	reg[31:0] state;

	assign dataExt[31:0] = oe ? 32'bz : state[31:0];
	assign dataInt[31:0] = oe ? state[31:0] : 32'bz;

	always @(posedge clk) begin
		if (!rst) begin
			state[31:0] = 32'b0;
		end else begin
			state[31:0] = state[31:0];
			if (oe) begin
				state[31:0] = dataExt[31:0];
			end else begin
				state[31:0] = dataInt[31:0];
			end
		end
	end
endmodule

