description:
Design a power-on reset circuit that generates a reset signal, rst, when the power signal, pwr, is active. The circuit utilizes an 8-bit counter, which increments on each clock cycle while the power is stable. When the counter reaches the maximum value of 255 (8'hFF), the rst output is asserted high, indicating an active reset state, before resetting the counter back to zero. If the power signal goes low, the counter is cleared, and the reset signal remains low until power is stable again. This module ensures that the system initializes correctly upon power-up.
module top_module(
  input pwr,
  input clk, // Added missing clk input
  output reg rst // Changed rst to reg type for assigning values
);

code:
module top_module(
  input pwr,
  input clk, // Added missing clk input
  output reg rst // Changed rst to reg type for assigning values
);reg [7:0] counter;
  reg reset_active;

  always @(posedge pwr) begin
    if (pwr) begin
      counter <= 0;
      reset_active <= 1;
    end else begin
      reset_active <= 0;
    end
  end

  always @(posedge clk) begin
    if (reset_active) begin
      if (counter == 8'hFF) begin
        rst <= 1;
        counter <= 0;
      end else begin
        rst <= 0;
        counter <= counter + 1;
      end
    end else begin
      rst <= 0;
    end
  end

endmodule

