module top_module(RESET_N,CLK, Z);input RESET_N;
   input CLK;
   output Z;

   reg  CURRENT_STATE;     
   reg  NEXT_STATE;        
   reg  Z;                 


   parameter  s0=0,        
              s1=1;

   always @ (CURRENT_STATE)    
      case (CURRENT_STATE)        
         s0:  Z = 1'b0;        
         s1:  Z = 1'b1;        
      endcase 

   always @ (CURRENT_STATE)     
      case (CURRENT_STATE)        
         s0:   NEXT_STATE=s1;   
         s1:   NEXT_STATE=s0;
      endcase 

   always @ (posedge CLK or negedge RESET_N)      
   begin
      if (! RESET_N)                              
         CURRENT_STATE <= s0;             
      else
         CURRENT_STATE <= NEXT_STATE;           
   end
endmodule

