description:
Implement the Verilog module based on the following description.
Build an 8-bit binary counter with synchronous active low reset signal and an enable signal. When the enable signal is high, the counter increments by 1.
// (1) reset_n: Resets the counter to 8'b00000000 when low.
// (2) enable: Enables the counter increment operation when high.
// (3) q: The value of the counter.

module top_module(
    input clk,
    input reset_n,
    input enable,
    output reg [7:0] q);

code:
module top_module(
    input clk,
    input reset_n,
    input enable,
    output reg [7:0] q
);

    always @(posedge clk) begin
        if (!reset_n) begin
            // Synchronous reset: Reset the counter to 8'b00000000
            q <= 8'b00000000;
        end else if (enable) begin
            // Counter increment: Increment by 1 when enabled
            q <= q + 1;
        end
    end

endmodule

